from AlgorithmImports import *
from datetime import timedelta


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(timedelta(0), timedelta(days=365))
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        # With regular-hours minute SPY data, this produces bars ending at
        # 09:35, 09:40, ... in the algorithm's New York time zone.
        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar

        self.current_slice = None
        self.held_contract = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.equity_exit_ticket = None
        self.block_entries_on = None

    def OnData(self, data: Slice):
        self.current_slice = data

        self.HandleUnexpectedSpyHolding()
        self.HandleExpirationSafety()
        self.HandleOptionExit(data)

        spy_bar = data.Bars.get(self.spy.Symbol)
        if spy_bar is not None:
            # Manual update ensures the five-minute handler can inspect this Slice.
            self.consolidator.Update(spy_bar)

    def OnFiveMinuteBar(self, bar: TradeBar):
        prior_fast = self.fast.Current.Value if self.fast.IsReady else None
        prior_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if prior_fast is not None and prior_slow is not None:
            is_bullish_cross = (
                prior_fast <= prior_slow
                and self.fast.Current.Value > self.slow.Current.Value
            )

            if is_bullish_cross:
                self.TryEnter(bar.EndTime)

        self.previous_fast = self.fast.Current.Value
        self.previous_slow = self.slow.Current.Value

    def TryEnter(self, bar_end_time):
        if not self.fast.IsReady or not self.slow.IsReady:
            return

        if not (bar_end_time.hour > 9 or
                (bar_end_time.hour == 9 and bar_end_time.minute >= 45)):
            return

        if not (bar_end_time.hour < 14 or
                (bar_end_time.hour == 14 and bar_end_time.minute <= 30)):
            return

        if self.block_entries_on == self.Time.date():
            return

        if self.HasOptionPosition() or self.IsOpen(self.entry_ticket) or self.IsOpen(self.exit_ticket):
            return

        if self.current_slice is None or not self.current_slice.OptionChains:
            self.Debug(f"{self.Time}: Entry skipped: no option chain in Slice.")
            return

        spy_price = self.Securities[self.spy.Symbol].Price
        if spy_price <= 0:
            self.Debug(f"{self.Time}: Entry skipped: invalid SPY price.")
            return

        algorithm_date = self.Time.date()
        eligible_contracts = []

        for chain in self.current_slice.OptionChains.Values:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()
                if (expiry_date - algorithm_date).days < 7:
                    continue

                eligible_contracts.append(contract)

        if not eligible_contracts:
            self.Debug(f"{self.Time}: Entry skipped: no call expiration at least 7 calendar days away.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in eligible_contracts)
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in eligible_contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Entry skipped: no qualifying call at expiry "
                f"{selected_expiry} with strike >= {minimum_strike:.2f}."
            )
            return

        selected = min(candidates, key=lambda c: (float(c.Strike), str(c.Symbol)))
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            f"{self.Time}: Entry submitted: {selected.Symbol}, "
            f"expiry {selected.Expiry.date()}, strike {selected.Strike}."
        )

    def HandleOptionExit(self, data: Slice):
        if not self.HasOptionPosition() or self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0 or self.IsOpen(self.exit_ticket):
            return

        expiry_date = self.held_contract.ID.Date.date()
        time_stop_date = self.PreviousTradingDay(expiry_date)

        if self.Time.date() == time_stop_date and self.Time.hour == 15 and self.Time.minute == 45:
            self.SubmitOptionExit("time stop before expiration")
            return

        if self.entry_price is None or self.entry_price <= 0:
            return

        contract = self.GetContractFromSlice(data, self.held_contract)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.SubmitOptionExit(
                f"50% profit target, midpoint {midpoint:.2f}, entry {self.entry_price:.2f}"
            )

    def HandleExpirationSafety(self):
        if not self.HasOptionPosition() or self.held_contract is None:
            return

        expiry_date = self.held_contract.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.block_entries_on = self.Time.date()
            self.SubmitOptionExit("expiration safety liquidation")

    def SubmitOptionExit(self, reason):
        if self.held_contract is None:
            return

        if self.IsOpen(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            self.Transactions.CancelOrder(self.exit_ticket.OrderId)

        self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
        self.Debug(f"{self.Time}: Exit submitted for {self.held_contract}: {reason}.")

    def HandleUnexpectedSpyHolding(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity
        if quantity == 0 or self.IsOpen(self.equity_exit_ticket):
            return

        self.Debug(
            f"{self.Time}: Unexpected SPY equity holding ({quantity}) from exercise/assignment; liquidating."
        )
        self.equity_exit_ticket = self.MarketOrder(self.spy.Symbol, -quantity)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Symbol == self.spy.Symbol:
            if order_event.Status == OrderStatus.Filled:
                self.HandleUnexpectedSpyHolding()
            return

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"{self.Time}: Entry filled: {self.held_contract} at {self.entry_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"{self.Time}: Entry order canceled or invalid.")
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"{self.Time}: Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}.")
                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_contract = None
                    self.entry_price = None
                    self.exit_ticket = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_ticket = None

    def GetContractFromSlice(self, data, symbol):
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def HasOptionPosition(self):
        return self.held_contract is not None and self.Portfolio[self.held_contract].Quantity != 0

    def PreviousTradingDay(self, date):
        candidate = date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def IsOpen(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        ]
