from AlgorithmImports import *
from datetime import datetime, timedelta, time


class FiveMinuteSpyCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.SetSecurityInitializer(
            BrokerageModelSecurityInitializer(
                self.BrokerageModel,
                FuncSecuritySeeder(self.GetLastKnownPrice)
            )
        )

        # Broad enough to include the required expirations and OTM strikes.
        self.Securities[self.option_symbol].SetFilter(
            lambda universe: universe.Strikes(-100, 100)
                                     .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        self.five_minute_bucket_end = None
        self.five_minute_samples = {}
        self.pending_entry = False
        self.pending_entry_time = None

        self.held_contract = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.no_entry_date = None

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_position()

        # Build five-minute bars explicitly from actual minute bars.
        if data.Bars.ContainsKey(self.spy):
            self._process_spy_minute_bar(data.Bars[self.spy])

        # Never deliberately carry an option into its expiration date.
        if self.held_contract is not None:
            expiry_date = self.held_contract.ID.Date.date()
            if self.Time.date() >= expiry_date:
                self.no_entry_date = self.Time.date()
                self._submit_exit("expiration processing")
            else:
                self._evaluate_position_exit(data)

        # The crossover handler sets this during this same Slice.
        if self.pending_entry:
            self._try_enter(data)
            self.pending_entry = False
            self.pending_entry_time = None

    def _process_spy_minute_bar(self, bar: TradeBar):
        minute_end = bar.EndTime.replace(second=0, microsecond=0)
        remainder = minute_end.minute % 5
        bucket_end = minute_end if remainder == 0 else (
            minute_end + timedelta(minutes=5 - remainder)
        )

        if self.five_minute_bucket_end is None:
            self.five_minute_bucket_end = bucket_end

        if bucket_end != self.five_minute_bucket_end:
            # A prior partial bucket is deliberately discarded.
            self.five_minute_samples = {}
            self.five_minute_bucket_end = bucket_end

        self.five_minute_samples[minute_end] = bar.Close

        if minute_end != bucket_end:
            return

        expected = {
            bucket_end - timedelta(minutes=offset)
            for offset in range(5)
        }

        if set(self.five_minute_samples.keys()) == expected:
            self._on_completed_five_minute_bar(bucket_end, bar.Close)

        # Missing minute data means no synthetic five-minute bar.
        self.five_minute_samples = {}

    def _on_completed_five_minute_bar(self, bar_end, close):
        previously_ready = self.fast.IsReady and self.slow.IsReady

        self.fast.Update(IndicatorDataPoint(bar_end, close))
        self.slow.Update(IndicatorDataPoint(bar_end, close))

        bullish_cross = (
            previously_ready
            and self.fast.IsReady
            and self.slow.IsReady
            and self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        self.previous_fast = self.fast.Current.Value
        self.previous_slow = self.slow.Current.Value

        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)
        if bullish_cross and eligible_time:
            self.pending_entry = True
            self.pending_entry_time = bar_end

    def _try_enter(self, data: Slice):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_contract is not None:
            return

        if self.entry_order_id is not None:
            return

        if self.exit_order_id is not None:
            return

        if self.Portfolio[self.spy].Quantity != 0:
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Skipped entry: SPY has no valid current price.")
            return

        candidates = []
        minimum_expiry = self.Time.date() + timedelta(days=7)

        for chain in data.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Expiry.date() < minimum_expiry:
                    continue
                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contracts in current Slice.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in candidates)
        minimum_strike = spy_price * 1.01

        contracts_at_expiry = [
            contract for contract in candidates
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= minimum_strike
        ]

        if not contracts_at_expiry:
            self.Debug("Skipped entry: no call strike at least 1% OTM at selected expiry.")
            return

        selected = min(
            contracts_at_expiry,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {selected.Expiry.date()}, "
            f"strike {selected.Strike}."
        )

    def _evaluate_position_exit(self, data: Slice):
        if self.held_contract is None:
            return

        expiry_date = self.held_contract.ID.Date.date()
        prior_trading_day = self._previous_spy_trading_day(expiry_date)

        if self.Time.date() == prior_trading_day and self.Time.time() == time(15, 45):
            self._submit_exit("15:45 pre-expiration time stop")
            return

        if self.entry_price is None or self.exit_order_id is not None:
            return

        midpoint = self._current_option_midpoint(data, self.held_contract)
        if midpoint is not None and midpoint >= self.entry_price * 1.50:
            self._submit_exit("50% profit target")

    def _current_option_midpoint(self, data: Slice, symbol):
        for chain in data.OptionChains.Values:
            if not chain.Contracts.ContainsKey(symbol):
                continue

            contract = chain.Contracts[symbol]
            bid = contract.BidPrice
            ask = contract.AskPrice

            if bid > 0 and ask > 0:
                return (bid + ask) / 2.0

        return None

    def _previous_spy_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(datetime.combine(candidate, time.min)):
            candidate -= timedelta(days=1)

        return candidate

    def _submit_exit(self, reason):
        if self.held_contract is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            self._clear_option_state()
            return

        # There should only ever be one exit, but remove any stale exit first.
        self.Transactions.CancelOpenOrders(self.held_contract)
        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted ({reason}): {self.held_contract}.")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.Debug(
            f"Unexpected SPY position from exercise/assignment: {quantity}. "
            "Submitting immediate liquidation."
        )
        self.MarketOrder(self.spy, -quantity)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_order_id == order_event.OrderId:
            if order_event.FillQuantity > 0:
                self.held_contract = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at {order_event.FillPrice}."
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_order_id = None

        if self.exit_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {order_event.FillPrice}."
                )
                self._clear_option_state()
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None

    def _clear_option_state(self):
        self.held_contract = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None

