from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def initialize(self) -> None:
        self.set_time_zone(TimeZones.NEW_YORK)
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)

        equity = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            fill_forward=False,
            extended_market_hours=False,
            data_normalization_mode=DataNormalizationMode.RAW
        )
        self.spy = equity.symbol

        option = self.add_option(self.spy, Resolution.MINUTE)
        option.set_filter(
            lambda universe: universe.strikes(-100, 100).expiration(0, 365).calls_only()
        )
        self.option_symbol = option.symbol

        consolidator = TradeBarConsolidator(self._five_minute_calendar)
        consolidator.data_consolidated += self._on_five_minute_bar
        self.subscription_manager.add_consolidator(self.spy, consolidator)

        self.closes = deque(maxlen=20)
        self.entry_signal_pending = False
        self.entry_order_id = None
        self.exit_order_id = None
        self.held_option = None
        self.entry_fill_price = None
        self.block_entries_on_date = None

    def _five_minute_calendar(self, dt: datetime) -> CalendarInfo:
        start = dt.replace(
            minute=(dt.minute // 5) * 5,
            second=0,
            microsecond=0
        )
        return CalendarInfo(start, timedelta(minutes=5))

    def _on_five_minute_bar(self, sender, bar: TradeBar) -> None:
        prior_fast = None
        prior_slow = None

        if len(self.closes) == 20:
            prior_fast = sum(list(self.closes)[-5:]) / 5
            prior_slow = sum(self.closes) / 20

        self.closes.append(bar.close)

        if prior_fast is None:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5
        current_slow = sum(self.closes) / 20

        eligible_time = (
            (bar.end_time.hour == 9 and bar.end_time.minute >= 45)
            or 10 <= bar.end_time.hour <= 13
            or (bar.end_time.hour == 14 and bar.end_time.minute <= 30)
        )

        if eligible_time and prior_fast <= prior_slow and current_fast > current_slow:
            self.entry_signal_pending = True

    def on_data(self, data: Slice) -> None:
        self._handle_unexpected_spy_position()

        if self._has_option_position():
            if self._expiration_processing_has_begun():
                self.block_entries_on_date = self.time.date()
                self._submit_exit("expiration safeguard")
                return

            if self._is_pre_expiry_time_stop():
                self._submit_exit("pre-expiry time stop")
            else:
                self._check_profit_target(data)

        if not self.entry_signal_pending:
            return

        self.entry_signal_pending = False

        if self.block_entries_on_date == self.time.date():
            return

        if self._has_option_position() or self.entry_order_id is not None:
            return

        self._submit_entry_from_current_chain(data)

    def _submit_entry_from_current_chain(self, data: Slice) -> None:
        chain = data.option_chains.get(self.option_symbol)
        if chain is None:
            self.debug("Entry skipped: no SPY option chain in Slice.")
            return

        spy_price = self.securities[self.spy].price
        if spy_price <= 0:
            self.debug("Entry skipped: invalid SPY price.")
            return

        today = self.time.date()
        eligible_expiries = sorted({
            contract.expiry.date()
            for contract in chain
            if contract.right == OptionRight.CALL
            and (contract.expiry.date() - today).days >= 7
        })

        if not eligible_expiries:
            self.debug("Entry skipped: no call expiration at least 7 calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.right == OptionRight.CALL
            and contract.expiry.date() == selected_expiry
            and contract.strike >= minimum_strike
        ]

        if not candidates:
            self.debug("Entry skipped: no qualifying 1% OTM call at selected expiry.")
            return

        contract = sorted(
            candidates,
            key=lambda c: (c.strike, str(c.symbol))
        )[0]

        ticket = self.market_order(contract.symbol, 1)
        self.entry_order_id = ticket.order_id
        self.debug(f"Entry submitted: {contract.symbol}")

    def _check_profit_target(self, data: Slice) -> None:
        quote = data.quote_bars.get(self.held_option)
        if quote is None or quote.bid is None or quote.ask is None:
            return

        bid = quote.bid.close
        ask = quote.ask.close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2
        if self.entry_fill_price is not None and midpoint >= self.entry_fill_price * 1.50:
            self._submit_exit("50% profit target")

    def _is_pre_expiry_time_stop(self) -> bool:
        if self.held_option is None:
            return False

        expiry_date = self.held_option.id.date.date()
        exchange_hours = self.securities[self.spy].exchange.hours
        prior_trading_day = exchange_hours.get_previous_trading_day(expiry_date)

        return (
            self.time.date() == prior_trading_day
            and self.time.hour == 15
            and self.time.minute == 45
        )

    def _expiration_processing_has_begun(self) -> bool:
        return (
            self.held_option is not None
            and self.time.date() >= self.held_option.id.date.date()
        )

    def _submit_exit(self, reason: str) -> None:
        if not self._has_option_position() or self.exit_order_id is not None:
            return

        for order in self.transactions.get_open_orders(self.held_option):
            self.transactions.cancel_order(order.id)

        quantity = self.portfolio[self.held_option].quantity
        ticket = self.market_order(self.held_option, -quantity)
        self.exit_order_id = ticket.order_id
        self.debug(f"Exit submitted ({reason}): {self.held_option}")

    def _has_option_position(self) -> bool:
        return (
            self.held_option is not None
            and self.portfolio[self.held_option].quantity != 0
        )

    def _handle_unexpected_spy_position(self) -> None:
        if self.portfolio[self.spy].quantity == 0:
            return

        if not self.transactions.get_open_orders(self.spy):
            self.debug("Unexpected SPY exercise/assignment position; liquidating.")
            self.market_order(self.spy, -self.portfolio[self.spy].quantity)

    def on_order_event(self, order_event: OrderEvent) -> None:
        if order_event.order_id == self.entry_order_id:
            if order_event.status == OrderStatus.FILLED:
                self.held_option = order_event.symbol
                self.entry_fill_price = order_event.fill_price
                self.entry_order_id = None
                self.debug(
                    f"Entry filled: {order_event.symbol} at {order_event.fill_price}"
                )
            elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self.entry_order_id = None
                self.debug(f"Entry canceled/invalid: {order_event.symbol}")

        if order_event.order_id == self.exit_order_id:
            if order_event.status == OrderStatus.FILLED:
                self.debug(f"Exit filled: {order_event.symbol} at {order_event.fill_price}")
                self.exit_order_id = None
                self.held_option = None
                self.entry_fill_price = None
            elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self.exit_order_id = None

    def on_assignment_order_event(self, order_event: OrderEvent) -> None:
        self.debug(f"Unexpected assignment event: {order_event.symbol}")
        self._handle_unexpected_spy_position()
